    public void save(@PathVariable("sheet") String sheet, @RequestParam("user") String user, @Val RateInput input,
            Rates rates, Audit audit, Rollup rollup) {
        Rollup.Snapshot before = rollup.take(sheet);
        rates.set(sheet, input);
        audit.record("RATE_SET sheet=" + sheet + " by=" + user + " grade=" + input.grade() + " rate="
                + input.pct().setScale(2, RoundingMode.UNNECESSARY).toPlainString()
                + (input.from() == null ? "" : " from=" + input.from()));
        rollup.record(sheet, user, before);
    }
}
package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.Set;
import java.util.regex.Pattern;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateRate {
    private static final Set<String> GRADES = Set.of("A", "B", "C");
    private static final Pattern PCT = Pattern.compile("\\d{1,7}(\\.\\d{1,2})?");

    public void validate(@RequestBody RateRequest request, Out<RateInput> body) throws InvalidRateException {
        String grade = request == null || request.grade() == null ? "" : request.grade().trim();
        String pct = request == null || request.pct() == null ? "" : request.pct().trim();
        String from = request == null || request.from() == null ? "" : request.from().trim();
        if (!GRADES.contains(grade)) {
            throw new InvalidRateException("Grade must be A, B or C");
        }
        if (!PCT.matcher(pct).matches()) {
            throw new InvalidRateException("The rate must be a percent of 0.00 or more with up to two decimals");
        }
        LocalDate on;
        try {
            on = from.isEmpty() ? null : LocalDate.parse(from);
        } catch (DateTimeParseException e) {
            throw new InvalidRateException("Not a valid from-date: " + from);
        }
        body.set(new RateInput(grade, new BigDecimal(pct), on));
    }
}
-- The sheet's rate for each grade: a percent with two decimals. A grade with no row has no rate.
CREATE TABLE rate (
    sheet VARCHAR(200)  NOT NULL,
    grade VARCHAR(1)    NOT NULL,
    pct   DECIMAL(9, 2) NOT NULL,
    PRIMARY KEY (sheet, grade)
);
-- A rate may carry a from-date: a grade may have several rates, one per from-date, and a claim uses the one
-- whose from-date is the latest on or before its date. A null from-date applies from the beginning of time.
-- from_key is the from-date as compared, so there is one rate per sheet, grade and from-date (null included).
ALTER TABLE rate DROP PRIMARY KEY;
ALTER TABLE rate ADD COLUMN from_date DATE;
ALTER TABLE rate ADD COLUMN from_key DATE GENERATED ALWAYS AS (COALESCE(from_date, DATE '0001-01-01'));
CREATE UNIQUE INDEX rate_sheet_grade_from ON rate (sheet, grade, from_key);
-- One row per sheet whose settings have been changed. A sheet with no row has today = the real date.
CREATE TABLE sheet (
    id    VARCHAR(200) PRIMARY KEY,
    today DATE NOT NULL
);

