import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { byUser } from '../session/session';
import { SheetPanels } from '../../slots/defs/sheetPanels';
import { GRADES } from '../people/people';
import { useSheetToday } from '../sheet/sheet';
import type { Grade } from '../people/people';
import { rateOf, ratesKey, ratesPath, useRates } from './rates';
import type { Rate } from './rates';

type Draft = { grade: Grade; pct: string; from: string };
const EMPTY: Draft = { grade: 'A', pct: '', from: '' };

// The sheet's rates: each grade's rate in force on the sheet's today (n/a when none), every rate with its
// from-date (a blank from-date applies from the start), and a form that sets one, replacing the rate already
// there for that grade and from-date.
function Rates({ sheet, user }: { sheet: string; user: string }) {
  const queryClient = useQueryClient();
  const { data: rates = [] } = useRates(sheet);
  const today = useSheetToday(sheet);
  const [draft, setDraft] = useState<Draft>(EMPTY);

  const save = useMutation({
    mutationFn: (body: Draft) => postJson<Rate[]>(byUser(ratesPath(sheet), user), body),
    onSuccess: (updated) => {
      queryClient.setQueryData(ratesKey(sheet), updated);
      setDraft((d) => ({ ...d, pct: '', from: '' }));
    },
  });
  const send = useSubmitOnce(save);

  const change = (next: Partial<Draft>) => {
    setDraft((d) => ({ ...d, ...next }));
    save.reset();
  };

  const submit = (e: FormEvent) => {
    e.preventDefault();
    // The server refuses a percent that is not 0.00 or more with up to two decimals, or a bad from-date.
    send(draft);
  };

  return (
    <section>
      <h2>Rates</h2>
      <form onSubmit={submit}>
        <label>
          Grade{' '}
          <select
            data-testid="rate-form-grade"
            value={draft.grade}
            onChange={(e) => change({ grade: e.target.value as Grade })}
          >
            {GRADES.map((g) => (
              <option key={g} value={g}>
                {g}
              </option>
            ))}
          </select>
        </label>{' '}
        <label>
          Rate %{' '}
          <input data-testid="rate-form-pct" value={draft.pct} onChange={(e) => change({ pct: e.target.value })} />
        </label>{' '}
        <label>
          From{' '}
          <input
            data-testid="rate-form-from"
            placeholder="yyyy-mm-dd (blank: from the start)"
            value={draft.from}
            onChange={(e) => change({ from: e.target.value })}
          />
        </label>{' '}
        <button type="submit" data-testid="rate-form-submit" disabled={save.isPending}>
          Set rate
        </button>
        {save.isError && (
          <span data-testid="rate-form-error" role="alert">
            {' '}A rate needs a grade of A, B or C and a percent of 0.00 or more with up to two decimals, and a from-date that is a valid date or blank.
          </span>
        )}
      </form>
      <table>
        <thead>
          <tr>
            <th>Grade</th>
            <th>Rate % today</th>
          </tr>
        </thead>
        <tbody>
          {GRADES.map((g) => (
            <tr key={g}>
              <td>{g}</td>
              <td data-testid={`rate-current-${g}`}>{rateOf(rates, g, today) ?? 'n/a'}</td>
            </tr>
          ))}
        </tbody>
      </table>
      <table>
        <thead>
          <tr>
            <th>Grade</th>
            <th>From</th>
            <th>Rate %</th>
          </tr>
        </thead>
        <tbody>
          {rates.map((r) => (
            <tr key={`${r.grade}-${r.from ?? 'start'}`} data-testid={`rate-row-${r.grade}-${r.from ?? 'start'}`}>
              <td>{r.grade}</td>
              <td data-testid="rate-from">{r.from ?? 'start'}</td>
              <td>
                <span data-testid="rate-pct">{r.pct}</span>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

export const contribution = SheetPanels.fill({ order: 5, Component: Rates });
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import type { Grade } from '../people/people';

/** A grade's rate: a percent with two decimals, in force from its from-date (yyyy-MM-dd; null when it
 *  applies from the beginning of time). */
export type Rate = { grade: Grade; pct: string; from: string | null };

export const ratesKey = (sheet: string) => ['rates', sheet] as const;

export const ratesPath = (sheet: string) => `/api/sheets/${encodeURIComponent(sheet)}/rates`;

/** Every rate on the sheet, by grade then from-date (the one with none first); a grade with no rate is absent. */
export function useRates(sheet: string) {
  return useQuery({
    queryKey: ratesKey(sheet),
    queryFn: () => getJson<Rate[]>(ratesPath(sheet)),
  });
}

/** The rate for a grade on a date (yyyy-MM-dd): the one whose from-date is the latest on or before it, or
 *  undefined when the date is before every rate the grade has (or the date is not yet known). */
export function rateOf(rates: Rate[], grade: Grade, date: string | undefined): string | undefined {
  if (date === undefined) return undefined;
  let found: Rate | undefined;
  for (const r of rates) {
    if (r.grade !== grade || (r.from !== null && r.from > date)) continue;
    if (found === undefined || (found.from ?? '') < (r.from ?? '')) found = r;
  }
  return found?.pct;
}

/** A two-decimal string as a whole number of hundredths. */
export function hundredths(value: string): bigint {
  const [whole, frac = ''] = value.split('.');
  return BigInt(whole) * 100n + BigInt(frac.padEnd(2, '0').slice(0, 2));
}

/** A whole number of hundredths as a two-decimal string. */
export function twoDecimals(cents: bigint): string {
  return `${cents / 100n}.${String(cents % 100n).padStart(2, '0')}`;
}

/** An amount times a percent, divided by 100, in hundredths rounded half to even (1.025 -> 1.02,
 *  1.035 -> 1.04); undefined when there is no rate. Worked in whole numbers so no float error shows. */
export function dueCents(amount: string, pct: string | undefined): bigint | undefined {
  if (pct === undefined) return undefined;
  const product = hundredths(amount) * hundredths(pct);
  const quotient = product / 10000n;
  const remainder = product % 10000n;
  if (remainder > 5000n || (remainder === 5000n && quotient % 2n === 1n)) return quotient + 1n;
  return quotient;
}

/** A due as the screen shows it: two decimals, or n/a when there is no rate. */
export function showDue(cents: bigint | undefined): string {
  return cents === undefined ? 'n/a' : twoDecimals(cents);
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import type { Person } from '../people/people';
import { dueCents, hundredths, rateOf, type Rate } from '../rates/rates';

/** Where a claim is in its life: DRAFT -> OPEN -> SETTLED, or DRAFT/OPEN -> VOID. */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'SETTLED' | 'VOID';

/** A status change a claim's row offers; the server refuses one its status does not allow. */
export type ClaimStatusChange = 'open' | 'settle' | 'void';

/** A claim: its amount with two decimals, its date (yyyy-MM-dd), its note, its status and its number on
 * the sheet (given when it is opened; null while a draft; kept once voided), and its due fixed when it was
 * settled (two decimals; null while live: until settled, and when its grade had no rate then), and the
 * user who opened it (null until opened; that user may not settle it), and whether its person's last statement
 * bound it, with the figure it bound (null when its grade had no rate then). */
export type Claim = {
  id: number;
  person: number;
  amount: string;
  date: string;
  note: string;
  status: ClaimStatus;
  number: number | null;
  settledDue: string | null;
  openedBy: string | null;
  stated: boolean;
  statedDue: string | null;
};

export const claimsKey = (sheet: string) => ['claims', sheet] as const;

export const claimsPath = (sheet: string) => `/api/sheets/${encodeURIComponent(sheet)}/claims`;

/** Every claim on the sheet, newest first. */
export function useClaims(sheet: string) {
  return useQuery({
    queryKey: claimsKey(sheet),
    queryFn: () => getJson<Claim[]>(claimsPath(sheet)),
  });
}

/** The claims that count toward claimed, due-total and every total: the OPEN and SETTLED ones, but not the OPEN
 *  ones of a person on hold. */
export function counted(claims: Claim[], people: Person[]): Claim[] {
  const held = new Set(people.filter((p) => p.held).map((p) => p.id));
  return claims.filter((c) => c.status === 'SETTLED' || (c.status === 'OPEN' && !held.has(c.person)));
}

/** The sum of the claims' amounts with two decimals, added in whole cents so no float error shows. */
export function claimed(claims: Claim[]): string {
  const cents = claims.reduce((sum, c) => {
    const [whole, frac = ''] = c.amount.split('.');
    return sum + Number(whole) * 100 + Number(frac.padEnd(2, '0'));
  }, 0);
  return `${Math.floor(cents / 100)}.${String(cents % 100).padStart(2, '0')}`;
}

/** Whether a claim keeps its figure whatever the rates: fixed when settled, or bound by a statement. */
export function fixed(claim: Claim): boolean {
  return claim.settledDue !== null || claim.stated;
}

/** A claim's due: the one fixed when it was settled, else the one its statement bound, else its amount at the
 *  grade's rate in force on its date. */
export function claimDueCents(claim: Claim, pct: string | undefined): bigint | undefined {
  if (claim.settledDue !== null) return hundredths(claim.settledDue);
  if (claim.stated) return claim.statedDue === null ? undefined : hundredths(claim.statedDue);
  return dueCents(claim.amount, pct);
}


/** A person's due-total: the sum of their counted claims' rounded figures (the claims of others are skipped). n/a (undefined) when their grade
 *  has no rate on the sheet's today, unless a settled or stated claim keeps a figure: then the figures there are. */
export function personDueCents(
  claims: Claim[],
  rates: Rate[],
  person: Person,
  today: string | undefined,
): bigint | undefined {
  const mine = counted(claims.filter((c) => c.person === person.id), [person]);
  if (rateOf(rates, person.grade, today) === undefined && !mine.some(fixed)) return undefined;
  return mine.reduce((sum, c) => sum + (claimDueCents(c, rateOf(rates, person.grade, c.date)) ?? 0n), 0n);
}
import type { ComponentType } from 'react';

// The contribution store. It imports NOTHING — that is deliberate: discovery (slots/discover.ts)
// pulls in every feature's contribution file, and those files reach a slot definition, which
// reaches defineSlot, which reaches this file. Keeping the arrows one-way (discover -> features ->
// defs -> Slot -> registry) is what stops the module graph forming a cycle.

export type Registered = {
  slot: string;
  order: number;
  /** Source file — the React key and the deterministic tie-break for equal `order`. */
  from: string;
  Component: ComponentType<never>;
};

const contributions: Registered[] = [];

/** Called once per contribution at startup, by slots/discover.ts. */
export function register(entry: Registered): void {
  contributions.push(entry);
}

export function forSlot(id: string): Registered[] {
  return contributions
    .filter((c) => c.slot === id)
    .sort((a, b) => a.order - b.order || a.from.localeCompare(b.from));
}
import { register } from './registry';
import type { Registered } from './registry';

// Discovery: every `features/**/*.slot.tsx` in the app is found here and registered, so there is
// no explicit list of features. A file exports `contribution`, or `contributions` for more than
// one. Imported once for its side effect by main.tsx.
const modules = import.meta.glob('../features/**/*.slot.tsx', { eager: true }) as Record<
  string,
  { contribution?: Omit<Registered, 'from' | 'order'> & { order?: number }; contributions?: Array<Omit<Registered, 'from' | 'order'> & { order?: number }> }
>;

for (const [from, mod] of Object.entries(modules)) {
  const declared = mod.contributions ?? (mod.contribution ? [mod.contribution] : []);
  for (const c of declared) {
    register({ ...c, from, order: c.order ?? 0 });
  }
}
import { createFileRoute } from '@tanstack/react-router';
import { SheetPanels } from '../slots/defs/sheetPanels';
import { SignIn } from '../features/session/SignIn';
import { SheetPicker } from '../features/session/SheetPicker';
import { useCurrentSheet, useCurrentUser } from '../features/session/session';

// The one screen. Sign in, then load a sheet by id; the sheet's panels (filled from sheet.panels)
// show everything kept for that sheet.
export const Route = createFileRoute('/')({
  component: Home,
});

function Home() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();

  if (!user) return <SignIn />;

  return (
    <>
      <p>
        Signed in as <strong data-testid="current-user">{user}</strong>
      </p>
      <SheetPicker />
      {sheet ? (
        // Keyed by sheet so per-sheet form drafts never carry over to another sheet.
        <div key={sheet}>
          <SheetPanels.Slot sheet={sheet} user={user} />
        </div>
      ) : (
        <p data-testid="home-empty">Nothing here yet.</p>
      )}
    </>
  );
}

